177	{
178	    rbnode_t *n = rb_malloc(sizeof *n);
179	    assert(n);
180	    n->key = rb_malloc(strlen(key) + 1);
181	    assert(n->key);
182	    memcpy(n->key, key, strlen(key) + 1);
