207	{
208	    /* Cases 1-4: red-red violation (a red node with a red child), at each
209	     * combination of which side of the root the red parent is on and which
210	     * side of that parent the red child is on. Ordering is correct and both
211	     * root-to-nil paths carry the same black count in every case, so only
212	     * the red-red rule is broken. */
213	    {
214	        static const struct {
215	            const char *name;
216	            const char *parent_key;
217	            int parent_is_left;      /* parent is root's left (1) or right (0) child */
218	            const char *child_key;
219	            int child_is_left;       /* red child is parent's left (1) or right (0) child */
220	        } cases[] = {
221	            { "validate_red_red_LL", "d", 1, "b", 1 },
222	            { "validate_red_red_LR", "d", 1, "f", 0 },
223	            { "validate_red_red_RL", "t", 0, "r", 1 },
224	            { "validate_red_red_RR", "t", 0, "v", 0 },
225	        };
226	        for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
227	            rbtree_t *t = rb_create(NULL);
228	            assert(t);
229	
230	            rbnode_t *parent = mk_node(t, cases[i].parent_key, RB_RED);
231	            rbnode_t *child = mk_node(t, cases[i].child_key, RB_RED);
232	            child->parent = parent;
233	            if (cases[i].child_is_left)
234	                parent->left = child;
235	            else
236	                parent->right = child;
237	
238	            rbnode_t *root = mk_node(t, "m", RB_BLACK);
239	            root->parent = t->nil;
240	            if (cases[i].parent_is_left) {
241	                root->left = parent;
242	                root->right = t->nil;
243	            } else {
244	                root->right = parent;
245	                root->left = t->nil;
246	            }
247	            parent->parent = root;
248	            t->root = root;
249	            t->size = 3;
250	
251	            assert(rb_validate(t) != 0);
252	            destroy_and_check_frees(t, 3);
253	            printf("ok - %s\n", cases[i].name);
254	        }
