257	    /* Cases 5-8: BST-order violation. The first two are immediate
258	     * parent/child inversions; the last two are deeper ancestor-bound
259	     * violations -- a node that's fine relative to its immediate parent but
260	     * violates a grandparent's bound, which a validator that only compares
261	     * a node to its direct parent (instead of threading a min/max bound)
262	     * would miss. All nodes BLACK so there's no red-red/black-height noise. */
263	    {
264	        rbtree_t *t = rb_create(NULL);
265	        assert(t);
266	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
267	        rbnode_t *left = mk_node(t, "z", RB_BLACK); /* should be < "m" */
268	        root->left = left;
269	        root->right = t->nil;
270	        root->parent = t->nil;
271	        left->parent = root;
272	        t->root = root;
273	        t->size = 2;
274	        assert(rb_validate(t) != 0);
