279	        rbtree_t *t = rb_create(NULL);
280	        assert(t);
281	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
282	        rbnode_t *right = mk_node(t, "b", RB_BLACK); /* should be > "m" */
283	        root->right = right;
284	        root->left = t->nil;
285	        root->parent = t->nil;
286	        right->parent = root;
287	        t->root = root;
288	        t->size = 2;
289	        assert(rb_validate(t) != 0);
290	        destroy_and_check_frees(t, 2);
291	        printf("ok - validate_bst_order_immediate_right_too_small\n");
292	    }
293	    {
294	        rbtree_t *t = rb_create(NULL);
295	        assert(t);
296	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
297	        rbnode_t *left = mk_node(t, "d", RB_BLACK);       /* valid: "d" < "m" */
298	        rbnode_t *deep = mk_node(t, "x", RB_BLACK);       /* valid vs "d": "x" > "d" ... */
299	        left->right = deep;                               /* ...but "x" > "m" violates root's bound */
300	        left->left = t->nil;
301	        deep->left = deep->right = t->nil;
302	        root->left = left;
303	        root->right = t->nil;
304	        root->parent = t->nil;
305	        left->parent = root;
306	        deep->parent = left;
307	        t->root = root;
308	        t->size = 3;
309	        assert(rb_validate(t) != 0);
310	        destroy_and_check_frees(t, 3);
311	        printf("ok - validate_bst_order_deep_left_exceeds_root\n");
312	    }
313	    {
314	        rbtree_t *t = rb_create(NULL);
315	        assert(t);
316	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
317	        rbnode_t *right = mk_node(t, "t", RB_BLACK);      /* valid: "t" > "m" */
318	        rbnode_t *deep = mk_node(t, "c", RB_BLACK);       /* valid vs "t": "c" < "t" ... */
319	        right->left = deep;                                /* ...but "c" < "m" violates root's bound */
320	        right->right = t->nil;
321	        deep->left = deep->right = t->nil;
322	        root->right = right;
323	        root->left = t->nil;
324	        root->parent = t->nil;
325	        right->parent = root;
326	        deep->parent = right;
327	        t->root = root;
328	        t->size = 3;
329	        assert(rb_validate(t) != 0);
330	        destroy_and_check_frees(t, 3);
331	        printf("ok - validate_bst_order_deep_right_below_root\n");
332	    }
