387	typedef struct {
388	    const char *name;
389	    const char *key;
390	    void *value;
391	    int fail_at;           /* 0 = no injected malloc failure */
392	    int expect_ok;         /* expect rb_insert to return 0 */
393	    int expect_free_count; /* rb_free calls during the faulted insert; -1 = n/a */
394	} insert_case_t;
395	
396	/* Cases 1-3: baseline success, and injected failure on each of
397	 * rb_insert's internal allocations. Order-agnostic about which
398	 * allocation (node struct vs. key copy) fail_at hits -- the header's
399	 * -1 contract must hold identically either way.
400	 *
401	 * expect_free_count mirrors create_cases' reasoning: fail_at=1 fails on the
402	 * very first rb_malloc call (the node struct), before anything else is
403	 * allocated, so cleanup frees nothing (0); fail_at=2 fails on the second call
404	 * (the key copy) after the node struct already succeeded, so cleanup frees
405	 * exactly that one allocation (1). */
406	static const insert_case_t insert_cases[] = {
407	    { "insert_into_empty_success", "alpha", "alpha-value", 0, 1, -1 },
408	    { "insert_fails_first_alloc",  "beta",  "beta-value",  1, 0,  0 },
409	    { "insert_fails_second_alloc", "gamma", "gamma-value", 2, 0,  1 },
410	};
411	
412	static void test_rb_insert(void)
413	{
414	    size_t n = sizeof insert_cases / sizeof insert_cases[0];
415	    /* invariant: each iteration gets a fresh tree, so a case's outcome
416	     * never depends on a prior case's inserts. */
417	    for (size_t i = 0; i < n; i++) {
418	        const insert_case_t *c = &insert_cases[i];
419	        rbtree_t *t = rb_create(NULL);
420	        assert(t);
421	
422	        if (c->fail_at)
423	            fault_malloc_arm(c->fail_at);
424	        int rc = rb_insert(t, c->key, c->value);
425	        if (c->fail_at) {
426	            assert(fault_malloc_free_count() == c->expect_free_count);
427	            fault_malloc_disarm();
428	        }
429	
430	        assert((rc == 0) == c->expect_ok);
431	        assert(rb_size(t) == (size_t)(c->expect_ok ? 1 : 0));
432	        assert(rb_find(t, c->key) == (c->expect_ok ? c->value : NULL));
433	
434	        rb_destroy(t);
435	        printf("ok - %s\n", c->name);
436	    }
437	
438	    /* Case 4: on allocation failure the tree must not call value_free,
439	     * and the caller must retain sole ownership of value. */
440	    {
441	        rbtree_t *t = rb_create(track_free);
442	        assert(t);
443	        for (int fail_at = 1; fail_at <= 2; fail_at++) {
444	            reset_tracking();
445	            char *v = malloc(8);
446	            assert(v);
447	            strcpy(v, "owned");
448	
449	            fault_malloc_arm(fail_at);
450	            int rc = rb_insert(t, "delta", v);
451	            fault_malloc_disarm();
452	
453	            assert(rc == -1);
454	            assert(!was_freed(v));
455	            assert(rb_size(t) == 0);
456	            free(v);   /* caller still owns it; must not double-free */
457	        }
458	        rb_destroy(t);
459	        printf("ok - insert_failure_value_not_consumed\n");
460	    }
461	
462	    /* Case 5: overwriting an existing key frees the old value via
463	     * value_free, keeps size unchanged, and matches by key content (two
464	     * distinct buffers with identical content, not the same pointer). */
465	    {
466	        rbtree_t *t = rb_create(track_free);
467	        assert(t);
468	        reset_tracking();
469	
470	        char key_first[] = "dup";
471	        char key_second[] = "dup";
472	        char *old_value = malloc(8);
473	        char *new_value = malloc(8);
474	        assert(old_value && new_value);
475	        strcpy(old_value, "old");
476	        strcpy(new_value, "new");
477	
478	        assert(rb_insert(t, key_first, old_value) == 0);
479	        assert(rb_insert(t, key_second, new_value) == 0);
480	
481	        assert(rb_size(t) == 1);
482	        assert(was_freed(old_value));
483	        assert(free_occurrences(old_value) == 1); /* not freed twice */
484	        assert(!was_freed(new_value));
485	        assert(rb_find(t, "dup") == new_value);
486	
487	        /* A second overwrite of the same key, armed so the very first
488	         * rb_malloc call would fail: overwriting an existing key must not
489	         * allocate a new node or key copy (the key is already stored), so a
490	         * correct rb_insert makes zero rb_malloc/rb_free calls here and
491	         * still returns 0 despite the arming. An implementation that always
492	         * allocates a fresh node on every insert (even for a duplicate key)
493	         * would either fail here or leak the discarded new node/key. */
494	        char *third_value = malloc(8);
495	        assert(third_value);
496	        strcpy(third_value, "third");
497	        fault_malloc_arm(1);
498	        int rc = rb_insert(t, "dup", third_value);
499	        assert(fault_malloc_free_count() == 0);
500	        fault_malloc_disarm();
501	        assert(rc == 0);
502	
503	        assert(rb_size(t) == 1);
504	        assert(free_occurrences(new_value) == 1); /* freed once, not twice */
505	        assert(!was_freed(third_value));
506	        assert(rb_find(t, "dup") == third_value);
507	
508	        /* A couple more surviving entries, so destroy has to walk multiple
509	         * nodes, not just the one left over from the overwrites. */
510	        char *extra1 = malloc(8);
511	        char *extra2 = malloc(8);
512	        assert(extra1 && extra2);
513	        strcpy(extra1, "extra1");
514	        strcpy(extra2, "extra2");
515	        assert(rb_insert(t, "extra-key-1", extra1) == 0);
516	        assert(rb_insert(t, "extra-key-2", extra2) == 0);
517	
518	        /* The repeated overwrite must have updated the existing node in
519	         * place, not left a stale second "dup" node behind: exactly 3
520	         * distinct keys should be visible to both validate and foreach. */
521	        assert(rb_validate(t) == 0);
522	        collect_ctx_t after_overwrite = {0};
523	        rb_foreach(t, collect_cb, &after_overwrite);
524	        assert(after_overwrite.n == 3);
525	
526	        rb_destroy(t);
527	        /* rb_destroy must run value_free on every value still owned by the
528	         * tree, not just the ones already freed by the earlier overwrites. */
529	        assert(was_freed(third_value));
530	        assert(was_freed(extra1));
531	        assert(was_freed(extra2));
532	        assert(freed_count == 5); /* old_value + new_value (overwrites) + 3 by destroy */
533	        printf("ok - insert_overwrite_frees_old_value\n");
534	    }
535	
536	    /* Case 6: distinct keys each get their own slot; size accumulates
537	     * and lookups don't cross-contaminate. Keys are inserted from mutable
538	     * buffers that get scribbled over right after each insert returns --
539	     * if rb_insert stored the caller's pointer instead of rb_malloc+memcpy
540	     * copying it, the lookups below would see the mutated content instead
541	     * of the original key. */
542	    {
543	        rbtree_t *t = rb_create(NULL);
544	        assert(t);
545	        char buf_a[] = "a-key", buf_m[] = "m-key", buf_z[] = "z-key";
546	        assert(rb_insert(t, buf_a, "a-value") == 0);
547	        assert(rb_insert(t, buf_m, "m-value") == 0);
548	        assert(rb_insert(t, buf_z, "z-value") == 0);
549	        memset(buf_a, 'X', strlen(buf_a));
550	        memset(buf_m, 'X', strlen(buf_m));
551	        memset(buf_z, 'X', strlen(buf_z));
552	
553	        assert(rb_size(t) == 3);
554	        assert(strcmp(rb_find(t, "a-key"), "a-value") == 0);
555	        assert(strcmp(rb_find(t, "m-key"), "m-value") == 0);
556	        assert(strcmp(rb_find(t, "z-key"), "z-value") == 0);
557	        assert(rb_find(t, "q-key") == NULL);
558	        assert(rb_find(t, "XXXXX") == NULL);
559	
560	        rb_destroy(t);
561	        printf("ok - insert_distinct_keys_prove_key_copy\n");
562	    }
563	
564	    /* Case 7: an ascending run of inserts forces left-rotations during
565	     * insert-fixup; rebalancing must preserve red-black invariants and
566	     * BST (sorted in-order) structure. */
567	    {
568	        static const char *keys[] = { "a", "b", "c", "d", "e", "f", "g" };
569	        size_t run_len = sizeof keys / sizeof keys[0];
570	        rbtree_t *t = rb_create(NULL);
571	        assert(t);
572	        /* invariant: every insert in this run succeeds before the next
573	         * begins, so size == i+1 after the i-th insert. */
574	        for (size_t i = 0; i < run_len; i++) {
575	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
576	            assert(rb_size(t) == i + 1);
577	        }
578	
579	        assert(rb_validate(t) == 0);
580	
581	        collect_ctx_t collected = {0};
582	        rb_foreach(t, collect_cb, &collected);
583	        assert(collected.n == (int)run_len);
584	        /* invariant: in-order traversal is strictly ascending since all
585	         * inserted keys are distinct. */
586	        for (int i = 0; i + 1 < collected.n; i++)
587	            assert(strcmp(collected.keys[i], collected.keys[i + 1]) < 0);
588	        /* invariant: foreach's value for each slot is exactly the pointer
589	         * that was inserted for that key (sorted order == insertion order
590	         * here, since the run was already ascending). */
591	        for (int i = 0; i < collected.n; i++)
592	            assert(collected.values[i] == (void *)keys[i]);
593	
594	        /* Every key must still be reachable by search after the rotations
595	         * this run triggered, not just present in the in-order walk. */
596	        for (size_t i = 0; i < run_len; i++)
597	            assert(rb_find(t, keys[i]) == (void *)keys[i]);
598	
599	        rb_destroy(t);
600	        printf("ok - insert_rebalances_ascending_run\n");
601	    }
602	
603	    /* Case 8: a descending run of inserts forces right-rotations during
604	     * insert-fixup; same invariants must hold. */
605	    {
606	        static const char *keys[] = { "g", "f", "e", "d", "c", "b", "a" };
607	        size_t run_len = sizeof keys / sizeof keys[0];
608	        rbtree_t *t = rb_create(NULL);
609	        assert(t);
610	        for (size_t i = 0; i < run_len; i++) {
611	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
612	            assert(rb_size(t) == i + 1);
613	        }
614	
615	        assert(rb_validate(t) == 0);
616	
617	        collect_ctx_t collected = {0};
618	        rb_foreach(t, collect_cb, &collected);
619	        assert(collected.n == (int)run_len);
620	        for (int i = 0; i + 1 < collected.n; i++)
621	            assert(strcmp(collected.keys[i], collected.keys[i + 1]) < 0);
622	        /* invariant: foreach's value for each slot is exactly the pointer
623	         * that was inserted for that key; sorted order is the reverse of
624	         * this run's (descending) insertion order. */
625	        for (int i = 0; i < collected.n; i++)
626	            assert(collected.values[i] == (void *)keys[run_len - 1 - i]);
627	
628	        /* Every key must still be reachable by search after the rotations
629	         * this run triggered, not just present in the in-order walk. */
630	        for (size_t i = 0; i < run_len; i++)
631	            assert(rb_find(t, keys[i]) == (void *)keys[i]);
632	
633	        rb_destroy(t);
634	        printf("ok - insert_rebalances_descending_run\n");
635	    }
