637	    /* Case 9: a minimal LR zig-zag. "c" becomes the black root; "a" inserts
638	     * red as its left child with the fixup loop not running (parent is the
639	     * root); "b" then inserts red as "a"'s right child. "a" is red and is
640	     * "c"'s left child while "b" is "a"'s right child -- the mismatched
641	     * shape that forces a left-rotation at "a" followed by a right-rotation
642	     * at "c" (a genuine double rotation, not two independent single ones). */
643	    {
644	        static const char *keys[] = { "c", "a", "b" };
645	        /* sorted[] references keys[]'s own elements (not fresh literals) so
646	         * the value-pointer check below compares against the exact pointer
647	         * that was inserted, not a look-alike duplicate. */
648	        const char *sorted[] = { keys[1], keys[2], keys[0] }; /* a, b, c */
649	        size_t run_len = sizeof keys / sizeof keys[0];
650	        rbtree_t *t = rb_create(NULL);
651	        assert(t);
652	        for (size_t i = 0; i < run_len; i++) {
653	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
654	            assert(rb_size(t) == i + 1);
655	        }
656	
657	        assert(rb_validate(t) == 0);
658	
659	        collect_ctx_t collected = {0};
660	        rb_foreach(t, collect_cb, &collected);
661	        assert(collected.n == (int)run_len);
662	        for (int i = 0; i < collected.n; i++) {
663	            assert(strcmp(collected.keys[i], sorted[i]) == 0);
664	            assert(collected.values[i] == (void *)sorted[i]);
665	        }
666	
667	        for (size_t i = 0; i < run_len; i++)
668	            assert(rb_find(t, keys[i]) == (void *)keys[i]);
669	
670	        rb_destroy(t);
671	        printf("ok - insert_rebalances_lr_zigzag\n");
672	    }
