674	    /* Case 10: a minimal RL zig-zag, the mirror of case 9. "a" becomes the
675	     * black root; "c" inserts red as its right child; "b" then inserts red
676	     * as "c"'s left child. "c" is "a"'s right child while "b" is "c"'s left
677	     * child, forcing a right-rotation at "c" then a left-rotation at "a". */
678	    {
679	        static const char *keys[] = { "a", "c", "b" };
680	        const char *sorted[] = { keys[0], keys[2], keys[1] }; /* a, b, c */
681	        size_t run_len = sizeof keys / sizeof keys[0];
682	        rbtree_t *t = rb_create(NULL);
683	        assert(t);
684	        for (size_t i = 0; i < run_len; i++) {
685	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
686	            assert(rb_size(t) == i + 1);
687	        }
688	
689	        assert(rb_validate(t) == 0);
690	
691	        collect_ctx_t collected = {0};
692	        rb_foreach(t, collect_cb, &collected);
693	        assert(collected.n == (int)run_len);
694	        for (int i = 0; i < collected.n; i++) {
695	            assert(strcmp(collected.keys[i], sorted[i]) == 0);
696	            assert(collected.values[i] == (void *)sorted[i]);
697	        }
698	
699	        for (size_t i = 0; i < run_len; i++)
700	            assert(rb_find(t, keys[i]) == (void *)keys[i]);
701	
702	        rb_destroy(t);
